class SnakeGame:
    def __init__(self, width, height, food):
        self.width = width
        self.height = height
        self.food = food
        self.food_index = 0
        self.body = [(0, 0)]
        self.score = 0

    def move(self, direction):
        hr, hc = self.body[0]
        if direction == 'U':
            hr -= 1
        elif direction == 'D':
            hr += 1
        elif direction == 'L':
            hc -= 1
        elif direction == 'R':
            hc += 1

        if hr < 0 or hr >= self.height or hc < 0 or hc >= self.width:
            return -1

        will_eat = (
            self.food_index < len(self.food)
            and self.food[self.food_index] == [hr, hc]
        )

        body_without_tail = self.body[:-1] if not will_eat else self.body
        if (hr, hc) in body_without_tail:
            return -1

        self.body.insert(0, (hr, hc))
        if will_eat:
            self.food_index += 1
            self.score += 1
        else:
            self.body.pop()

        return self.score


if __name__ == "__main__":
    game = SnakeGame(3, 2, [[1, 2], [0, 1]])
    for d in ["R", "D", "R", "U", "L", "U"]:
        print(game.move(d))

