import java.util.*;

public class Main {
    static class SnakeGame {
        int width, height, foodIndex = 0, score = 0;
        int[][] food;
        List<int[]> body = new ArrayList<>();

        SnakeGame(int width, int height, int[][] food) {
            this.width = width;
            this.height = height;
            this.food = food;
            body.add(new int[]{0, 0});
        }

        int move(String direction) {
            int[] head = body.get(0);
            int hr = head[0], hc = head[1];
            if (direction.equals("U")) hr--;
            else if (direction.equals("D")) hr++;
            else if (direction.equals("L")) hc--;
            else if (direction.equals("R")) hc++;

            if (hr < 0 || hr >= height || hc < 0 || hc >= width) return -1;

            boolean willEat = foodIndex < food.length && food[foodIndex][0] == hr && food[foodIndex][1] == hc;

            int checkLimit = willEat ? body.size() : body.size() - 1;
            for (int i = 0; i < checkLimit; i++) {
                if (body.get(i)[0] == hr && body.get(i)[1] == hc) return -1;
            }

            body.add(0, new int[]{hr, hc});
            if (willEat) {
                foodIndex++;
                score++;
            } else {
                body.remove(body.size() - 1);
            }
            return score;
        }
    }

    public static void main(String[] args) {
        SnakeGame game = new SnakeGame(3, 2, new int[][]{{1, 2}, {0, 1}});
        for (String d : new String[]{"R", "D", "R", "U", "L", "U"}) {
            System.out.println(game.move(d));
        }
    }
}

