#include <bits/stdc++.h>
using namespace std;

class SnakeGame {
public:
    int width, height, foodIndex = 0, score = 0;
    vector<vector<int>> food;
    deque<pair<int,int>> body;

    SnakeGame(int width, int height, vector<vector<int>> food) : width(width), height(height), food(food) {
        body.push_back({0, 0});
    }

    int move(string direction) {
        int hr = body.front().first, hc = body.front().second;
        if (direction == "U") hr--;
        else if (direction == "D") hr++;
        else if (direction == "L") hc--;
        else if (direction == "R") hc++;

        if (hr < 0 || hr >= height || hc < 0 || hc >= width) return -1;

        bool willEat = foodIndex < (int)food.size() && food[foodIndex][0] == hr && food[foodIndex][1] == hc;

        int checkLimit = willEat ? body.size() : body.size() - 1;
        int i = 0;
        for (auto& seg : body) {
            if (i >= checkLimit) break;
            if (seg.first == hr && seg.second == hc) return -1;
            i++;
        }

        body.push_front({hr, hc});
        if (willEat) {
            foodIndex++;
            score++;
        } else {
            body.pop_back();
        }
        return score;
    }
};

int main() {
    vector<vector<int>> food = {{1, 2}, {0, 1}};
    SnakeGame game(3, 2, food);
    for (string d : {"R", "D", "R", "U", "L", "U"}) {
        cout << game.move(d) << endl;
    }
    return 0;
}

