import java.util.*;

public class Main {
    static class SnakeGame {
        int width, height, foodIndex = 0, score = 0;
        int[][] food;
        Deque<int[]> body = new ArrayDeque<>();
        Set<Long> bodySet = new HashSet<>();

        SnakeGame(int width, int height, int[][] food) {
            this.width = width;
            this.height = height;
            this.food = food;
            body.addFirst(new int[]{0, 0});
            bodySet.add(encode(0, 0));
        }

        long encode(int r, int c) {
            return (long) r * 100000 + c;
        }

        int move(String direction) {
            int[] head = body.peekFirst();
            int hr = head[0], hc = head[1];
            if (direction.equals("U")) hr--;
            else if (direction.equals("D")) hr++;
            else if (direction.equals("L")) hc--;
            else if (direction.equals("R")) hc++;

            if (hr < 0 || hr >= height || hc < 0 || hc >= width) return -1;

            boolean willEat = foodIndex < food.length && food[foodIndex][0] == hr && food[foodIndex][1] == hc;

            int[] tail = body.peekLast();
            if (!willEat) bodySet.remove(encode(tail[0], tail[1]));

            if (bodySet.contains(encode(hr, hc))) return -1;

            body.addFirst(new int[]{hr, hc});
            bodySet.add(encode(hr, hc));
            if (willEat) {
                foodIndex++;
                score++;
            } else {
                body.pollLast();
            }
            return score;
        }
    }

    public static void main(String[] args) {
        SnakeGame game = new SnakeGame(3, 2, new int[][]{{1, 2}, {0, 1}});
        for (String d : new String[]{"R", "D", "R", "U", "L", "U"}) {
            System.out.println(game.move(d));
        }
    }
}

